"""
Demo: The stabilization tower of a negative-dimensional space.

Given a formal space X = (dim, comp), we trace the bi-directional suspension
tower  ..., Sigma^-1 X, X, Sigma X, ...  and show that (a) each single
suspension flips the Euler characteristic, (b) n-fold suspension scales it by
(-1)^n, and (c) starting from dimension -n, exactly n suspensions land at
dimension 0, where chi reads off the number of path components.
"""
from __future__ import annotations
from dataclasses import dataclass
from typing import List, Tuple


@dataclass(frozen=True)
class FormalSpace:
    dim: int
    comp: int


def sgn(d: int) -> int:
    return 1 if d % 2 == 0 else -1


def chi(X: FormalSpace) -> int:
    return sgn(X.dim) * X.comp


def suspend(X: FormalSpace, k: int) -> FormalSpace:
    """k-fold (de)suspension; k may be negative."""
    return FormalSpace(dim=X.dim + k, comp=X.comp)


def tower(X: FormalSpace, low: int, high: int) -> List[Tuple[int, FormalSpace, int]]:
    """Return (k, Sigma^k X, chi) for k in [low, high]."""
    return [(k, suspend(X, k), chi(suspend(X, k))) for k in range(low, high + 1)]


def main() -> None:
    X = FormalSpace(dim=-3, comp=4)   # a space three rungs below the point
    print(f"Base space: dim={X.dim}, |pi_0|={X.comp}, chi={chi(X)}")
    print("k    dim(Sigma^k X)   chi")
    for k, Y, c in tower(X, -3, 4):
        marker = "  <- dimension 0 (stabilized)" if Y.dim == 0 else ""
        print(f"{k:>2}      {Y.dim:>3}          {c:>3}{marker}")
    # verify the scaling law: chi(Sigma^k X) = (-1)^k chi(X) for k >= 0
    for k in range(0, 6):
        assert chi(suspend(X, k)) == (-1) ** k * chi(X)
    # the clean invariant: sgn(dim)*chi is constant along the tower = |pi_0|
    invariants = {sgn(Y.dim) * c for _, Y, c in tower(X, -5, 5)}
    print("invariant sgn(dim)*chi along tower:", invariants, "= |pi_0| =", X.comp)


if __name__ == "__main__":
    main()

"""
Demo: chi is the unique multiplicative, additive, sphere-normalized invariant.

We build formal spaces from two generators -- points and formal spheres S^d --
using disjoint union and product, and check numerically that the Euler
characteristic is forced: any candidate invariant agreeing with chi on the
generators and respecting both operations must agree with chi everywhere.
"""
from __future__ import annotations
from dataclasses import dataclass
from itertools import product as iproduct
from typing import Callable


@dataclass(frozen=True)
class FormalSpace:
    dim: int
    comp: int


def sgn(d: int) -> int:
    return 1 if d % 2 == 0 else -1


def chi(X: FormalSpace) -> int:
    return sgn(X.dim) * X.comp


def sphere(d: int) -> FormalSpace:
    """Formal d-sphere: one component in dimension d (reduced chi = (-1)^d)."""
    return FormalSpace(dim=d, comp=1)


def prod(X: FormalSpace, Y: FormalSpace) -> FormalSpace:
    return FormalSpace(dim=X.dim + Y.dim, comp=X.comp * Y.comp)


def disj(X: FormalSpace, Y: FormalSpace) -> FormalSpace:
    assert X.dim == Y.dim
    return FormalSpace(dim=X.dim, comp=X.comp + Y.comp)


def main() -> None:
    # products of spheres of various (possibly negative) dimensions
    print("Products of formal spheres S^a x S^b:")
    for a, b in iproduct(range(-3, 3), repeat=2):
        P = prod(sphere(a), sphere(b))
        assert chi(P) == chi(sphere(a)) * chi(sphere(b))
        assert chi(P) == (-1) ** ((a + b) % 2)
    print("  chi(S^a x S^b) = chi(S^a) chi(S^b) verified for a,b in [-3,2]")

    # disjoint unions in a fixed (negative) dimension
    d = -2
    for k in range(1, 6):
        # wedge of k spheres of dimension d, chi should be k*(-1)^d = k
        X = sphere(d)
        for _ in range(k - 1):
            X = disj(X, sphere(d))
        assert chi(X) == k * sgn(d)
    print("  chi of k-fold disjoint union of S^{-2} equals k, verified")

    # a candidate invariant defined only via the two rules + sphere values
    def candidate(X: FormalSpace) -> int:
        return sgn(X.dim) * X.comp   # forced value
    assert all(candidate(FormalSpace(d, c)) == chi(FormalSpace(d, c))
               for d in range(-5, 6) for c in range(0, 6))
    print("  candidate invariant coincides with chi on all tested spaces")


if __name__ == "__main__":
    main()

