from typing import Dict


def sgn(d: int) -> int:
    return 1 if d % 2 == 0 else -1


def graded_euler_characteristic(betti: Dict[int, int]) -> int:
    """
    Alternating (sign-weighted) sum of Betti numbers over all integer degrees:
    chi = sum_i (-1)^i b_i, with the support allowed to include negative degrees.
    """
    return sum(sgn(degree) * b for degree, b in betti.items())


def genus_surface_chi(g: int) -> int:
    """Euler characteristic of the closed orientable genus-g surface: 2 - 2g."""
    return graded_euler_characteristic({0: 1, 1: 2 * g, 2: 1})
